import 'package:fluent_ui/fluent_ui.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'dashboard_bloc.dart';import 'system_info.dart';import 'monitoring/system_monitor_bloc.dart';
class DashboardPage extends StatelessWidget{const DashboardPage({super.key});@override Widget build(BuildContext context)=>ScaffoldPage.scrollable(header:PageHeader(title:const Text('System overview'),commandBar:Button(onPressed:()=>context.read<DashboardBloc>().add(const DashboardRefreshRequested()),child:const Row(children:[Icon(FluentIcons.refresh),SizedBox(width:8),Text('Refresh')]))),children:[BlocBuilder<SystemMonitorBloc,SystemMonitorState>(builder:(_,s){final m=s.metrics;return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text('Live performance',style:FluentTheme.of(context).typography.subtitle)),ToggleSwitch(checked:s.status!=SystemMonitorStatus.paused,content:Text(s.status==SystemMonitorStatus.paused?'Monitoring off':'Monitoring on'),onChanged:(v)=>context.read<SystemMonitorBloc>().add(v?const SystemMonitorStarted():const SystemMonitorStopped()))]),const SizedBox(height:12),if(s.status==SystemMonitorStatus.loading&&m==null)const ProgressBar(),if(s.error!=null)InfoBar(title:const Text('Monitoring issue'),content:Text(s.error!),severity:InfoBarSeverity.warning),if(m!=null)LayoutBuilder(builder:(_,c){final w=c.maxWidth>=700?(c.maxWidth-16)/2:c.maxWidth;return Wrap(spacing:16,runSpacing:16,children:[metric(w,'CPU usage',m.cpuPercent,'Updated ${m.sampledAt.toLocal().toString().split('.').first}'),metric(w,'Memory usage',m.memoryPercent,'${m.usedMemoryGb.toStringAsFixed(1)} GB used of ${m.totalMemoryGb.toStringAsFixed(1)} GB')]);}),const SizedBox(height:24)]);}),BlocBuilder<DashboardBloc,DashboardState>(builder:(_,s){if(s.status==DashboardStatus.loading&&s.info==null)return const Center(child:ProgressRing());if(s.info==null)return InfoBar(title:const Text('Information unavailable'),content:Text(s.error??'Waiting'));return Overview(s.info!);})]);Widget metric(double w,String title,double value,String detail)=>SizedBox(width:w,child:Card(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(title)),Text('${value.round()}%')]),const SizedBox(height:12),ProgressBar(value:value),const SizedBox(height:8),Text(detail)])));}
class Overview extends StatelessWidget{const Overview(this.info,{super.key});final SystemInfo info;@override Widget build(BuildContext context)=>LayoutBuilder(builder:(_,c){final w=c.maxWidth>=900?(c.maxWidth-32)/3:c.maxWidth>=560?(c.maxWidth-16)/2:c.maxWidth;return Wrap(spacing:16,runSpacing:16,children:[box(w,'Computer',[info.computer,'User: ${info.user}']),box(w,'Operating system',[info.os,'Version ${info.version}']),box(w,'Processor',[info.cpu,'${info.cores} logical processors']),box(w,'Memory snapshot',['${(info.ramUsage*100).round()}% used','${info.freeRam.toStringAsFixed(1)} GB free']),box(w,'Drive ${info.drive}',['${(info.diskUsage*100).round()}% used','${info.freeDisk.toStringAsFixed(1)} GB free']),box(w,'Session',['Booted: ${info.booted?.toLocal().toString().split('.').first??'Unknown'}','Updated: ${info.updated.toLocal().toString().split('.').first}'])]);});Widget box(double w,String title,List<String>lines)=>SizedBox(width:w,child:Card(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title),const SizedBox(height:12),...lines.map(Text.new)])));}
